ee:message.ee:set-payload:
%dw 2.0 output application/json
import modules::GlobalFunctions as global
--- { "pqrType": "TESR", "pqrDate": global::fechaActual(), "system": "MDM", "orderNumber": vars.orderNumber, "connectionNumber": "", "identification": vars.requestOrder.customer.documentNumber, "identificationType": vars.requestOrder.customer.documentType, "user": "MDM" }

%dw 2.0
output application/json

fun obtenerValorFiltro(tipoTramite) =
    tipoTramite match {
        case "TESR" -> vars.objectServicio_Tramite.Id_Cuenta_Facturacion
        case "TRAMITE LTE" -> vars.objectServicioActivo.Integration_Id
        else -> null
    }


---
{
	"query": {
    "aggregate": p('mongo-db-sapi.collections.facturacion'),
    "pipeline": [
      {
        // Envolvemos el resultado en un $match para que Mongo filtre
        "\$match": {
        	"Cuenta_Facturacion": obtenerValorFiltro(upper(vars.requestOrder.through.throughType))
        }
      }
    ],
    "cursor": {}
  }
}

%dw 2.0 output application/json
import modules::GlobalFunctions as global
var TESR = vars.requestOrder.through.throughType var fecha_corte = vars.responseMongo.result[0].Fecha_Corte_Facturacion
fun pad2(n: Number): String = if (n < 10) "0" ++ (n as String) else (n as String)
fun crearFecha(anno: Number, mes: Number, dia: Number): Date = ((anno as String) ++ "-" ++ pad2(mes) ++ "-" ++ pad2(dia)) as Date {format: "yyyy-MM-dd"}
fun primerDiaMes(fecha: Date): Date = crearFecha(fecha.year, fecha.month, 1)
fun ultimoDiaMes(fecha: Date): Date = (primerDiaMes(fecha) + |P1M|) - |P1D|
var UMBRAL_DIAS = 3
fun fechaEjecucionCancelacionVoluntaria(fechaCorteFacturacion: Number): Date = do { var hoy = now() as Date var intDiaCorte = fechaCorteFacturacion default 0 var corteEsFinDeMes = (intDiaCorte == 0) or (intDiaCorte > 31) --- if (corteEsFinDeMes) ultimoDiaMes(hoy) else do { var fechaCorteMesActual = crearFecha(hoy.year, hoy.month, intDiaCorte) var diasParaCorte = (fechaCorteMesActual - hoy) as Number {unit: "days"} --- if (diasParaCorte >= UMBRAL_DIAS) fechaCorteMesActual else fechaCorteMesActual + |P1M| } }
fun generarFechaEjecucionPorCiclo(tramite: String, fechaCorteFacturacion: Number): Date | Null = tramite match { case t if (t == TESR or t == "Tramite LTE") -> fechaEjecucionCancelacionVoluntaria(fechaCorteFacturacion) else -> null }
var fecha = generarFechaEjecucionPorCiclo( TESR default "TESR", fecha_corte default "0" )
var cf = vars.responseMongo.result[0] --- { objectCuentaFacturacion: { "_id": { "\$oid": "000000000000000000000000" }, Fecha_Creacion: global::parseFechaFlexible(cf.Fecha_Creacion), Fecha_Modificacion: global::parseFechaFlexible(cf.Fecha_Modificacion), Usuario_Modificacion: cf.Usuario_Modificador, Usuario_Creacion: cf.Usuario_Creador, Actualizacion_Extractor: null, Id_Cuenta_Facturacion: cf.Cuenta_Facturacion, Cliente_Basico: { "_id": { "\$oid": "000000000000000000000000" }, Fecha_Creacion: null, Fecha_Modificacion: null, Usuario_Modificacion: null, Usuario_Creacion: null, Actualizacion_Extractor: null, Id_Cuenta_Cliente: 0, Tipo_Documento: cf.Tipo_Documento, Numero_Documento: cf.Numero_Identificacion }, Estado: { Codigo: cf.Estado, Descripcion: null, Fecha: null, CodigoExcepcion: 0, Excepcion: null }, Tipo_Facturacion: cf.Tipo_Factura, Tipo_Factura: cf.Tipo_Factura, Tipo_Envio: cf.Tipo_Entrega_Factura, Valor_Factura: 0.0, Valor_Factura_Formato: null, Email_Facturacion: cf.Correo_Electronico, Ciclo_Facturacion: cf.Ciclo_Facturacion, Dia_Corte: cf.Fecha_Corte_Facturacion, Mora: false, Id_Direccion_Facturacion: cf.Id_Direccion_Facturacion as Number default 0, Fecha_Suspension: null, Ciclo_Charging: cf.Ciclo_Charging as Number default 0, Codigo_Ciclo_Charging: cf.Codigo_Ciclo_Charging as Number default 0, Cuentas_Servicio: null, Fecha_Corte_Facturacion: cf.Fecha_Corte_Facturacion, Pago_Rec: cf.Pago_Rec default [] }, fechaEjecucion: if (fecha != null) { "\$date": (fecha as String {format: "yyyy-MM-dd"}) ++ "T00:00:00.000Z" } else null }

ee:variables.ee:set-variable:
%dw 2.0 output application/json
import modules::GlobalFunctions as global
// Definición de la función fun buscarAccionAdd(listaAcciones) = ( (listaAcciones filter ($.Accion == global::homologarAccion(vars.requestOrder.through.throughType)))[0] default {} )
var objectAccion = buscarAccionAdd(vars.claseServicioHijo.Acciones)
--- do { // 1. Tomamos lo que ya tiene la variable o inicializamos con vacío var acumulado = vars.serviciosHijos default []
// 2. Creamos el objeto del consecutivo actual var resultadoActual = { "Accion": objectAccion.Accion, "Agendamiento": objectAccion.Agendamiento, "Aprovisionamiento": objectAccion.Aprovisionamiento, "Disponibilidad": objectAccion.Disponibilidad, "Atributos": global::enriquecerAtributos(payload.Atributos,vars.claseServicioHijo.Atributos default []) , "Clase_Servicio": vars.claseServicioHijo.Nombre, "Codigo_Configuracion": payload.Codigo_Configuracion, "Extendido": vars.claseServicioHijo.Extendida, "Id_Clase_Servicio": payload.Id_Clase_Servicio, "Id_Item": payload.Id_Item, "Id_Servicio": payload.Id_Servicio, "Id_Subtipo_Servicio": payload.Id_Subtipo_Servicio, "Id_Tipo_Servicio": payload.Id_Tipo_Servicio, "Nombre": payload.Nombre, "Nuevo": true, "Puertos": [], "Rollback": [], "Commit": [], "Servicios_Hijos": [] } --- // 3. Retornamos la lista con el nuevo elemento al final acumulado ++ [resultadoActual] }

